#!/bin/sh
# 모의 서버로 게임을 띄워요 (Firebase 대신 window.__seed 메모리 DB). 사용: tools/ui_mock.sh [저장소 루트] [포트]
#   사이트는 /tmp/.../scratchpad/mtest_<포트>/site 에 복사돼요. 페이지에서 window.__seed = { players: { me1: {...} } }, window.__uid = 'me1' 로 시드를 넣어요.
#   테스트용 손잡이 window.__T (openSheet·closeSheet·npcGet·evPlay·storyPlay 등)도 같이 넣어요
ROOT=${1:-/home/user/magionacademy}; PORT=${2:-8766}
S=/tmp/claude-0/-home-user/d683bb50-b1f3-59a3-8e5f-5f21e64e8c5a/scratchpad/mtest_$PORT; mkdir -p $S/site/mock
cd $ROOT/public && cp -r art audio data world.js stargaze_sky.js xfx.js xfx2.js dream.js td.js tdmap.js fonts credits.json firebase-config.js manifest.webmanifest $S/site/ 2>/dev/null; cp $ROOT/tools/mock/*.js $S/site/mock/
sed "s#const FB = 'https://www.gstatic.com/firebasejs/10.12.2/';#const FB = './mock/';#" index.html > $S/site/index.html
sed -i "s#^document.addEventListener('keydown', e => { if (evOn#window.__T = { dfGet: () => ({ ctl: dfCtl, st: dfSt, pick: dfPick, host: dfHost, on: dfOn, zone: dfZone }), dfSet: (k, v) => { if (k === 'AD') Object.assign(AD, v); }, dfHostStart: () => dfHostStart(), dfHostTick: () => dfHostTick(), dfOpen: () => dfOpen(), meGet: () => ({ coin: me.coin, mana: me.inv.mana, spx: xEx().spx, lnr: me.lnr, sdt: me.sdt, pk: me.pk, buff: (me.buffs || {}).pump }), sgGet: () => ({ ctl: sgCtl, join: sgJoin, lit: sgLit, buffs: me.buffs, fx: ['crop_growth','move_speed','exp_gain'].map(k => sgFx(k)) }), sgAct: (a, v) => sgAdminAct(a, v), sgTick: () => sgAdminTick(true), sgOpen: p => sgOpen(p), sgCard: () => adminStargazeHTML(), sgSync: () => sgSync(), sgLight: id => sgLight(id), fishGet: () => fishing ? ({ st: fishing.st, pos: fishing.pos, zc: fishing.zc, zw: fishing.zw }) : null, fishDir: d => { if (fishing) fishing.dir = d; }, mqb: { st: () => mqState(), qid: () => mqQuest() ? mqQuest().id : null, stage: () => mqStage(), objs: () => mqObjs().map((o, i) => ({ ...o, i })), talk: id => mqTalk(id), talkClient: () => { const q = mqQuest(); if (!q) return 0; mqTalk(q.client); return 1; }, clientId: () => mqQuest().client, ending: () => { playEnding(); return 1; }, setq: (q, st, ph) => { const s = mqState(); s.q = q; s.st = st; s.ph = ph; s.prog = {}; save(); syncNpcs(); },  scene: () => mqScene(mqQuest().id, mqState().st, 'complete').then(x => JSON.stringify(x).length), play: () => { mqPlay(mqQuest(), mqState().st, 'complete'); return 1; }, check: () => mqCheck(), onTalk: id => mqOnTalk(id), give: (k, n) => mqGive(k, n), list: () => MQ.list, flag: f => { me.nflag = me.nflag || {}; me.nflag[f] = 1; }, evOn: () => !!evOn, tick: () => mqTick(), save: () => save() }, admSend: (u, e) => adminMailSend(u, e), admGift: () => adminGiftHTML(), admOv: () => adminEventOverview(), meFull: () => ({ cr: me.cr, eggs: me.eggs, coin: me.coin, inv: me.inv, buffs: me.buffs, exam: me.exam, mana: me.mana, spx: xEx().spx }), tutGet: () => me.tut, bgm: () => BGM, tutTalk: () => tutTalk(), tutHook: k => tutHook(k), pkSet: (p, v) => F.set(F.ref(db, p), v), pkGet: () => ({ ctl: pkCtl, pts: pkPts, w: pkW, st: pkStage(), done: pkDone() }), pkAct: (k, m) => pkAct(k, m), pkBless: () => pkBless(), pkBubble: () => pkBubble(), setInv: (k, n) => { me.inv[k] = n; }, roomGet: () => me.room, placeFurn: f => placeFurn(f), lnSet: (p, v) => F.set(F.ref(db, p), v), lnGet: () => ({ ctl: lnCtl, cnt: lnCnt, color: lnColor, boost: lnBoost }), lnDrop: s => lnDrop(s), pzSet: (p, v) => F.set(F.ref(db, p), v), pzGet: () => ({ ctl: pzCtl, board: pzBoard, own: pzOwn }), pzDrop: s => pzDrop(s), dfMD: () => dfMD, xAll_: j => xAll(j), xDesc_: (o, l) => xDesc(o, l), xMk: (...a) => xMkUnit(...a), XJ_: XJ, xSt_: (j, L, k) => xSt(j, L, k), recipePaper: f => recipePaper(f), gainKnow: () => gainKnow(), rest: () => rest(), playEnding: () => playEnding(), xFoeTarget: () => xFoeTarget(), xcoHost: () => xcoHost(), xbGet: () => xb, xM: () => xM, xvGet: () => xv, xRun: () => xEx().run, xAct: (...a) => xAct(...a), xSetRg: i => { xRgSel = i }, xSB: k => xStartBattle(k), BGM, penDoor: i => World.onPenDoor(i), penClaim: i => penClaim(i), myPen: () => myPenIdx(), evPlay: (...a) => evPlay(...a), npcGet: id => npcGet(id), npcAvOf: id => npcAv(npcGet(id)), babyGet: () => ({ b: me.baby, seen: me.babySeen, inv: me.inv, cut: babyCutOn, ctl: babyCtl, pick: babyPickV }), meRaw: () => me, babyTick: () => babyTick(), snowGet: () => ({ m: me.snow, st: snowSt, ctl: snowCtl, roll: snowRoll, buff: (me.buffs || {}).snow, inv: Object.fromEntries(Object.entries(me.inv).filter(([,n])=>n>0)) }), snowTap: () => snowTap(), snowDbg: () => [snowCutOn, babyCutOn, !!evOn, sheetOn, mqArriving, World.where(), snowOn()], npcEvent: (...a) => npcEvent(...a), NL, me: () => me, syncNpcs: () => syncNpcs(), npcMenu: n => npcMenu(n), hearts: id => hearts(id), weatherToday: () => weatherToday(), bandNow: () => bandNow(), castSprite: (id) => castSprite(id, {}), fill: (t, id) => fillVars(t, id), openSheet: (a, b) => openSheet(a, b), closeSheet: () => closeSheet(), storyPlay: (c) => storyPlay(c, STORY[c - 1].intro.concat(STORY[c - 1].ending), STORY[c - 1].name), render: () => render(), save: () => save(), toast: t => toast(t), openRoom: g => openRoom(g), hostStart: () => hostStart(), leaveRoom: () => leaveRoom(), xPoseDbg: (...a) => xPoseDbg(...a), xHandScan: () => xHandScan(), gameInfo: () => ({ room, g: G ? G.g : null, score: G ? G.score : null, ret: gameRet, spots: World.getSpots().length }), trEv: (o, d) => trEv(o, d), trGive: i => trGive(i) };\n&#" $S/site/index.html
cd $S/site && (curl -s -o /dev/null http://localhost:$PORT/ || (nohup python3 -m http.server $PORT >/dev/null 2>&1 &)); sleep 1
echo "http://localhost:$PORT/  (site: $S/site)"
